/**
 Unit tests for the built `Cargo.lock` reader.

 @module
 */

import {
  describe,
  expect,
  it,
} from '@monochromatic-dev/module-test/ts';

import {
  isRegistryPackage,
  parseCargoLock,
} from '../dist/final/node/index.mjs';

/**
 Lockfile with a path root, a registry package, a git package, and malformed entries.
 */
const LOCK = [
  '# This file is automatically @generated by Cargo.',
  'version = 4',
  '',
  '[[package]]',
  'name = "app"',
  'version = "0.1.0"',
  'dependencies = [',
  ' "anyhow",',
  ' "syn 2.0.110",',
  ']',
  '',
  '[[package]]',
  'name = "anyhow"',
  'version = "1.0.104"',
  'source = "registry+https://github.com/rust-lang/crates.io-index"',
  'checksum = "0000"',
  '',
  '[[package]]',
  'name = "helix-core"',
  'version = "25.7.1"',
  'source = "git+https://github.com/helix-editor/helix?rev=abc#abc"',
  '',
  '[[package]]',
  'name = "no-version"',
  '',
  '[[package]]',
  'name = "bad-deps"',
  'version = "1.0.0"',
  'dependencies = [1, "ok"]',
  '',
].join('\n',);

await describe({
  name: parseCargoLock.name,
  children: [
    it({
      name: 'reads name, version, source, and dependency strings, skipping entries without a version',
      fn: async () => {
        expect(parseCargoLock(LOCK,),).toEqual([
          { name: 'app', version: '0.1.0', source: '', dependencies: ['anyhow', 'syn 2.0.110',], },
          { name: 'anyhow', version: '1.0.104', source: 'registry+https://github.com/rust-lang/crates.io-index', dependencies: [], },
          { name: 'helix-core', version: '25.7.1', source: 'git+https://github.com/helix-editor/helix?rev=abc#abc', dependencies: [], },
          { name: 'bad-deps', version: '1.0.0', source: '', dependencies: ['ok',], },
        ],);
      },
    },),
    it({
      name: 'returns no packages for a lockfile without [[package]] entries',
      fn: async () => {
        expect(parseCargoLock('version = 4\n',),).toEqual([],);
      },
    },),
    it({
      name: 'throws on text that is not TOML',
      fn: async () => {
        expect(function parseBroken(): void {
          parseCargoLock('[[package]\nname = ',);
        },).toThrow();
      },
    },),
  ],
},);

await describe({
  name: isRegistryPackage.name,
  children: [
    it({
      name: 'accepts registry sources and rejects git and path packages',
      fn: async () => {
        expect(parseCargoLock(LOCK,).map(isRegistryPackage,),).toEqual([false, true, false, false,],);
      },
    },),
  ],
},);
